HERO_STR_STATIC(hero_str_535d1b68, "module_name_reserved");
HERO_STR_STATIC(hero_str_3441f6cd, "` would be the module `library`, and that name is the language's own \342\200\224 \302\2471.11's Tier 2 is compiled into every program under it");
HERO_STR_STATIC(hero_str_3ad5aff3, "rename the file: any other stem will do, and nothing else in the language is reserved this way");
