HERO_STR_STATIC(hero_str_4e380f0a, "` \342\200\224 clang read the header and could not find it");
HERO_STR_STATIC(hero_str_4984a51, "an `extern` names what the header already has (\302\2474.19): check the spelling, or name the header that does declare `");
HERO_STR_STATIC(hero_str_2d81771, "the header declares `");
HERO_STR_STATIC(hero_str_70ce66e, "did you mean");
HERO_STR_STATIC(hero_str_1fc2f816, "did you mean '");
HERO_STR_STATIC(hero_str_74547321, "clang offered no correction");
HERO_STR_STATIC(hero_str_1ef0dbf6, "missing field '");
HERO_STR_STATIC(hero_str_44788dd6, "not a missing-field line");
HERO_STR_STATIC(hero_str_5def2f2c, "no position on the line");
HERO_STR_STATIC(hero_str_50f6728b, "no group record sits on that line");
HERO_STR_STATIC(hero_str_2d35ebc5, "ffi_incomplete_record");
HERO_STR_STATIC(hero_str_7a6d9d44, "` does not name `");
HERO_STR_STATIC(hero_str_7cb31b7e, "`, and `");
HERO_STR_STATIC(hero_str_1984bf76, "` says the struct has it \342\200\224 a group's `record` IS the header's struct, so a field left out is a field C fills with zero");
HERO_STR_STATIC(hero_str_2a09c51c, "the assertions above check every field you DO name and cannot see one you leave out: a `");
HERO_STR_STATIC(hero_str_475dee3d, "` built here would carry a zero `");
